import os
import re
from collections import defaultdict

repo = "/bench/repo"

# Collect all packages under internal/
internal_packages = {}
for root, dirs, files in os.walk(os.path.join(repo, "internal")):
    for f in files:
        if f.endswith(".go") and not f.endswith("_test.go"):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()
            pkg_match = re.search(r'^package\s+(\w+)', content, re.M)
            if not pkg_match:
                continue
            pkg = pkg_match.group(1)
            rel_dir = os.path.relpath(root, repo)
            import_path = "github.com/usememos/memos/" + rel_dir.replace(os.sep, "/")
            internal_packages[path] = (pkg, import_path, content)

# Parse exported and unexported funcs/methods in internal/
# func Name( or func (r *Type) Name(
func_pattern = re.compile(
    r'^func\s+(?:\([^)]+\)\s+)?([A-Za-z_]\w*)\s*\(',
    re.M
)

symbols = []  # (qual_name, short_name, path, is_method, recv_type)
for path, (pkg, import_path, content) in internal_packages.items():
    for m in func_pattern.finditer(content):
        name = m.group(1)
        # check if method
        line_start = content.rfind('\n', 0, m.start()) + 1
        line = content[line_start:m.end()]
        meth = re.match(r'^func\s+\(([^)]+)\)\s+(\w+)', line)
        if meth:
            recv = meth.group(1).strip()
            recv_type = re.sub(r'^\*', '', recv.split()[-1])
            qual = f"{recv_type}.{name}"
            symbols.append((qual, name, path, True, recv_type, pkg, import_path))
        else:
            qual = name
            symbols.append((qual, name, path, False, None, pkg, import_path))

# Read all non-test go files for call counting
all_files = []
for root, dirs, files in os.walk(repo):
    if '.git' in root.split(os.sep):
        continue
    for f in files:
        if f.endswith(".go") and not f.endswith("_test.go"):
            all_files.append(os.path.join(root, f))

file_contents = {}
for path in all_files:
    with open(path) as fh:
        file_contents[path] = fh.read()

def count_calls(symbol_name, defining_path, is_method, recv_type, pkg, import_path):
    count = 0
    callers = set()

    # Patterns for calls
    patterns = [
        re.compile(r'\b' + re.escape(symbol_name) + r'\s*\('),
    ]
    if is_method:
        patterns.append(re.compile(r'\.' + re.escape(symbol_name) + r'\s*\('))

    # Package-qualified calls like markdown.Service or util.X
    patterns.append(re.compile(r'\b' + re.escape(pkg) + r'\.' + re.escape(symbol_name) + r'\s*\('))

    # import alias - harder; also match last component of import path
    last_comp = import_path.split("/")[-1]
    patterns.append(re.compile(r'\b' + re.escape(last_comp) + r'\.' + re.escape(symbol_name) + r'\s*\('))

    for path, content in file_contents.items():
        if path == defining_path:
            # exclude definition line itself
            def_content = content
            for m in func_pattern.finditer(content):
                if m.group(1) == symbol_name:
                    line_start = content.rfind('\n', 0, m.start()) + 1
                    line_end = content.find('\n', m.start())
                    if line_end == -1:
                        line_end = len(content)
                    # rough: skip one occurrence
                    pass
        for pat in patterns:
            for m in pat.finditer(content):
                # skip if in defining file and looks like func declaration
                pos = m.start()
                line_start = content.rfind('\n', 0, pos) + 1
                line = content[line_start:content.find('\n', pos)]
                if 'func ' in line and symbol_name + '(' in line:
                    continue
                count += 1
                callers.add(path)
    return count, len(callers)

# Focus on exported symbols first (capitalized) - more likely cross-package
results = []
seen = set()
for qual, name, path, is_method, recv_type, pkg, import_path in symbols:
    key = (path, name, recv_type)
    if key in seen:
        continue
    seen.add(key)
    if not name[0].isupper() and not is_method:
        continue  # skip unexported funcs initially

    cnt, caller_files = count_calls(name, path, is_method, recv_type, pkg, import_path)
    if cnt > 0:
        results.append((cnt, caller_files, qual, path, name))

results.sort(reverse=True)
print("TOP 30 by raw match count:")
for cnt, cf, qual, path, name in results[:30]:
    rel = os.path.relpath(path, repo)
    print(f"{cnt:4d} files={cf:3d}  {qual}  —  {rel}")

