use strict;
use warnings;
my $repo = "/bench/repo";

# Find all func/method declarations in internal/
my @symbols;
for my $path (glob("$repo/internal/*/*.go"), glob("$repo/internal/*/*/*.go"), glob("$repo/internal/*/*/*/*.go")) {
    next if $path =~ /_test\.go$/;
    open my $fh, "<", $path or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    $content =~ /^package\s+(\w+)/m;
    my $pkg = $1 // "unknown";
    my $rel = $path; $rel =~ s/^\Q$repo\E\/?//;
    my $import = "github.com/usememos/memos/" . $rel;
    $import =~ s/\/[^\/]+\.go$//;

    while ($content =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_]\w*)\s*\(/mg) {
        my ($recv, $name) = ($1, $2);
        my $qual = $name;
        my $recv_type;
        if (defined $recv) {
            ($recv_type) = $recv =~ /(\*?[A-Za-z_]\w*)$/;
            $recv_type =~ s/^\*//;
            $qual = "$recv_type.$name";
        }
        push @symbols, { name => $name, qual => $qual, path => $rel, pkg => $pkg, import => $import, method => defined $recv, recv => $recv_type };
    }
}

# Read all non-test go files
my @files;
for my $root ($repo, "$repo/server", "$repo/store", "$repo/cmd", "$repo/internal") {
    # walk manually
}
use File::Find;
my %contents;
find(sub {
    return unless /\.go$/;
    return if /_test\.go$/;
    open my $fh, "<", $File::Find::name or return;
    my $c = do { local $/; <$fh> };
    close $fh;
    $contents{$File::Find::name} = $c;
}, $repo);

my @results;
for my $s (@symbols) {
    my $name = $s->{name};
    my $pkg = $s->{pkg};
    my $last = (split /\//, $s->{import})[-1];
    my $count = 0;
    my %callers;
    my $defpath = "$repo/$s->{path}";

    for my ($fpath, $content) (each %contents) {
        while ($content =~ /\b\Q$name\E\s*\(/g) {
            my $pos = pos($content) - length($name) - 1;
            my $line_start = rindex($content, "\n", $pos - 1) + 1;
            my $line_end = index($content, "\n", $pos);
            $line_end = length($content) if $line_end < 0;
            my $line = substr($content, $line_start, $line_end - $line_start);
            next if $line =~ /^func\s+/;  # skip declarations
            $count++;
            $callers{$fpath} = 1;
        }
        # package qualified
        for my $prefix ($pkg, $last) {
            my $pat = qr/\b\Q$prefix\E\.\Q$name\E\s*\(/;
            while ($content =~ /$pat/g) {
                $count++;
                $callers{$fpath} = 1;
            }
        }
    }
    push @results, [$count, scalar keys %callers, $s->{qual}, $s->{path}] if $count > 0;
}

@results = sort { $b->[0] <=> $a->[0] } @results;
print "TOP 25:\n";
for my $i (0..24) {
    last unless $results[$i];
    printf "%4d files=%3d  %s  —  %s\n", @{$results[$i]};
}
'

