perl -e '
my $repo = "/bench/repo";

# collect defining symbols: name, file, line, kind (func/method), recv
my @defs;
my @files;
for my $dir ("$repo/internal") {
    opendir my $dh, $dir or die;
    my @queue = grep { -d "$dir/$_" && $_ ne "." && $_ ne ".." } readdir $dh;
    closedir $dh;
    push @queue, $dir;
    while (@queue) {
        my $path = shift @queue;
        opendir $dh, $path or next;
        for my $e (readdir $dh) {
            next if $e eq "." || $e eq "..";
            my $fp = "$path/$e";
            if (-d $fp) { push @queue, $fp; next; }
            next unless $e =~ /\.go$/ && $e !~ /_test\.go$/;
            push @files, $fp;
            open my $fh, "<", $fp or next;
            my @lines = <$fh>;
            close $fh;
            my $rel = $fp; $rel =~ s/^\Q$repo\E\/?//;
            for my $i (0..$#lines) {
                my $L = $lines[$i];
                if ($L =~ /^func\s+\(([^)]+)\)\s+([A-Za-z_]\w*)\s*\(/) {
                    my ($recv, $name) = ($1, $2);
                    my $rt = $recv; $rt =~ s/^\*//; $rt = (split /\s+/, $rt)[-1];
                    push @defs, { name=>$name, recv=>$rt, file=>$rel, line=>$i+1, qual=>"$rt.$name" };
                } elsif ($L =~ /^func\s+([A-Za-z_]\w*)\s*\(/) {
                    push @defs, { name=>$1, recv=>undef, file=>$rel, line=>$i+1, qual=>$1 };
                }
            }
        }
    }
}

# all non-test go file contents
my %all;
for my $root ($repo, "$repo/server", "$repo/store", "$repo/cmd", "$repo/internal", "$repo/proto") {
}
# walk with glob
for my $fp (glob("$repo/*"), glob("$repo/*/*"), glob("$repo/*/*/*"), glob("$repo/*/*/*/*"), glob("$repo/*/*/*/*/*")) {
    next unless -f $fp && $fp =~ /\.go$/ && $fp !~ /_test\.go$/;
    open my $fh, "<", $fp or next;
    my $c = do { local $/; <$fh> };
    close $fh;
    $all{$fp} = $c;
}

sub count_calls {
    my ($def) = @_;
    my $name = $def->{name};
    my $cnt = 0;
    my $def_full = "$repo/$def->{file}";
    for my ($fp, $content) (each %all) {
        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $L = $lines[$i];
            next if $fp eq $def_full && ($i+1) == $def->{line};
            next if $L =~ /^func\s+/;
            # method call .Name(
            my $m = () = $L =~ /\.$name\s*\(/g;
            $cnt += $m;
            # bare Name( for funcs - risky for short names; only if not method
            if (!defined $def->{recv}) {
                $m = () = $L =~ /\b$name\s*\(/g;
                $cnt += $m;
            }
        }
    }
    return $cnt;
}

my @res;
for my $d (@defs) {
    my $c = count_calls($d);
    push @res, [$c, $d->{qual}, $d->{file}] if $c > 0;
}
@res = sort { $b->[0] <=> $a->[0] || $a->[2] cmp $b->[2] } @res;
print "TOP 30 (note: short names may over-count):\n";
for (0..29) {
    last unless $res[$_];
    printf "%4d  %s  —  %s\n", @{$res[$_]} if $res[$_][0] >= 3;
}
' 2>&1 | head -40

perl << 'PERL'
my $repo = "/bench/repo";

my @all_files = map { chomp; $_ } <> ; 
# read from stdin - will pass files differently

PERL
find /bench/repo/internal -name "*.go" ! -name "*_test.go" -print0 | xargs -0 awk '
  /^func \(.*\) [A-Za-z_][A-Za-z0-9_]*\(/ || /^func [A-Za-z_][A-Za-z0-9_]*\(/ {
    f=FILENAME; sub(/^.*\//,"",f); # no use full path from FILENAME
    file=FILENAME; sub("/bench/repo/","",file)
    if ($0 ~ /^func \(/) {
      match($0, /^func \([^)]+\) ([A-Za-z_][A-Za-z0-9_]*)\(/, a)
      name=a[1]
      match($0, /^func \(([^)]+)\)/, b)
      recv=b[1]; sub(/^.* /,"",recv); sub(/^\*/,"",recv)
      qual=recv"."name
    } else {
      match($0, /^func ([A-Za-z_][A-Za-z0-9_]*)\(/, a)
      name=a[1]; qual=name; recv=""
    }
    print qual "\t" name "\t" recv "\t" file
  }
' > /tmp/internal_defs.txt
