    while (<$fh>) {
      $cnt-- if /^func\s+/ && /\b$name\s*\(/;
    }
  }
  return $cnt > 0 ? $cnt : 0;
}

my @res;
for my $d (@defs) {
  my $c = count_for($d);
  push @res, [$c, $d->{qual}, $d->{file}] if $c >= 3;
}
@res = sort { $b->[0] <=> $a->[0] || $a->[2] cmp $b->[2] } @res;
for (@res[0..39]) {
  printf "%4d  %s  —  %s\n", @$_;
}
