+my $repo = "/bench/repo";
+open my $df, "<", "/tmp/internal_defs.txt" or die;
+my @defs;
+while (<$df>) {
+  chomp;
+  my ($qual, $name, $recv, $file) = split /\t/, $_;
+  push @defs, {qual=>$qual, name=>$name, recv=>$recv||"", file=>$file};
+}
+
+open my $af, "-|", "find", $repo, "-name", "*.go", "!", "-name", "*_test.go" or die;
+chomp(my @all = <$af>);
+close $af;
+
+my %contents;
+for my $f (@all) {
+  open my $fh, "<", $f or next;
+  $contents{$f} = do { local $/; <$fh> };
+  close $fh;
+}
+
+sub count_for {
+  my ($d) = @_;
+  my $name = $d->{name};
+  my $recv = $d->{recv};
+  my $cnt = 0;
+  for my $f (@all) {
+    my $c = $contents{$f};
+    if ($recv ne "") {
+      # common receiver variable names in defining file
+      my @recv_vars = ("r", "pc", "s", "p", "e", "d", "c", "h", "j", "m", "t", "n", "a", "b");
+      for my $v (@recv_vars) {
+        while ($c =~ /\b\Q$v\E\.\Q$name\E\s*\(/g) { $cnt++ }
+      }
+      # also generic .Name( for methods
+      while ($c =~ /\.\Q$name\E\s*\(/g) { $cnt++ }
+    } else {
+      while ($c =~ /\b\Q$name\E\s*\(/g) { $cnt++ }
+    }
+  }
+  # subtract declarations in defining file
+  my $defpath = "$repo/$d->{file}";
+  open my $fh, "<", $defpath or return $cnt;
+  while (<$fh>) {
+    if (/^func\s+/ && /\b\Q$name\E\s*\(/) { $cnt-- }
+  }
+  close $fh;
+  return $cnt > 0 ? $cnt : 0;
+}
+
+my @res;
+for my $d (@defs) {
+  next if length($d->{name}) < 3; # skip Is, Or, etc.
+  next if $d->{name} eq "New";   # skip ambiguous
+  next if $d->{name} eq "init";
+  my $c = count_for($d);
+  push @res, [$c, $d->{qual}, $d->{file}] if $c >= 5;
+}
+@res = sort { $b->[0] <=> $a->[0] || $a->[2] cmp $b->[2] } @res;
+for (0..24) {
